"use strict";

// ---------- Learn units: Grades 4 to 6 (original content written to CAPS topics) ----------
const P = t => `<p>${t}</p>`;
const PASS_HARE = `<div class="passage-text"><p><b>Why Hare Has Long Ears</b> <span class="muted">(a 2to.iQ folktale)</span></p>
<p>Long ago, Hare had short, round ears, just like Mouse. Hare was quick, but he never listened.</p>
<p>One afternoon, Grandmother Tortoise called all the animals together. "Tonight the rain will be heavy," she said slowly. "The river will flood. Move your homes to the high rocks."</p>
<p>All the animals listened, except Hare. He was busy racing his own shadow across the veld.</p>
<p>That night, the water rose higher and higher. Hare woke up wet and cold, and he had to swim all the way to the high rocks.</p>
<p>In the morning, Hare sat shivering beside Tortoise. "I was foolish," he said. "I wish I could hear better."</p>
<p>Tortoise smiled. "Then stretch your ears towards wise words," she said.</p>
<p>So every day, Hare stretched his ears to listen to the wind, the birds and his friends. His ears grew longer and longer. And that is why, to this day, Hare has long ears and hears danger before anyone else.</p></div>`;
const PASS_PENGUIN = `<div class="passage-text"><p><b>African Penguins</b></p>
<p><b>Where they live.</b> African penguins live along the coasts of South Africa and Namibia. One of the best places to see them is Boulders Beach, near Simon's Town in the Western Cape.</p>
<p><b>What they look like.</b> An African penguin is about 60 centimetres tall. It has a black back, a white front and a black stripe across its chest. Above each eye there is a patch of pink skin. The pink patches help the penguin to lose heat when it is hot.</p>
<p><b>What they eat.</b> African penguins are strong, fast swimmers. They dive into the sea to catch small fish, such as sardines and anchovies.</p>
<p><b>A loud call.</b> African penguins make a loud call that sounds like a donkey braying.</p>
<p><b>Why they need help.</b> There are far fewer African penguins today than there were a hundred years ago. Many people are working to protect them and the fish they eat.</p>
<div class="factbox"><b>Fact box</b><br>Height: about 60 cm<br>Food: small fish<br>Home: the coasts of South Africa and Namibia</div></div>`;
const PASS_AD = `<div class="passage-text ad"><p class="ad-big">NEW! Sunrise Oat Rusks</p>
<p><b>The best start to every school day!</b></p>
<p>Packed with crunchy oats and golden honey.</p>
<p>9 out of 10 children say they love the crunch!*</p>
<p>Only R34,99 for a box of 12.</p>
<p><b>Hurry! This special price ends on Friday.</b></p>
<p>Be a Sunrise champion. Start your day the Sunrise way!</p>
<p class="muted" style="font-size:0.8rem">*Based on a taste test with 20 children. Sunrise Oat Rusks is a made-up product for this lesson.</p></div>`;

