      { type: "mcq", q: "What was Hare doing while the others listened?", options: ["Racing his shadow", "Sleeping", "Eating grass", "Swimming"], answer: 0, hints: ["Find the sentence that starts \"All the animals listened, except Hare.\"", "Read the next sentence.", "He was busy with a game on the veld."], explain: "Hare was racing his own shadow across the veld." },
      { type: "order", q: "Put the events in the order they happened.", items: ["Tortoise warns the animals", "Hare does not listen", "The river floods", "Hare stretches his ears every day"], orderLabel: "first to last", hints: ["What happens at the very beginning?", "The flood happens at night.", "The ending explains why Hare's ears are long."], explain: "Warning, not listening, the flood, then Hare's ears grow long." },
      { type: "mcq", q: "Why did Hare say, \"I was foolish\"?", options: ["He had not listened to the warning", "He lost a race", "He was hungry", "He did not like rain"], answer: 0, hints: ["What happened to Hare that night?", "Why did he get wet when the others did not?", "He did not move his home because he did not listen."], explain: "Hare got wet and cold because he did not listen to Tortoise's warning." },
      { type: "mcq", q: "What lesson does this folktale teach?", options: ["It is wise to listen", "Running fast is the most important thing", "Rivers are always dangerous", "Tortoises are slow"], answer: 0, hints: ["Think about what Hare learnt.", "What did Tortoise tell Hare to do?", "\"Stretch your ears towards wise words.\""], explain: "The story teaches that it is wise to listen, especially to good advice." },
      { type: "sort", q: "Sort the words into nouns and adjectives.", items: ["river", "short", "ears", "cold", "rocks", "wise"], bins: ["Nouns", "Adjectives"], answer: [0, 1, 0, 1, 0, 1], hints: ["A noun is a thing. An adjective describes a thing.", "Can you put \"the\" in front of it? Then it is probably a noun.", "short, cold and wise describe things."], explain: "river, ears and rocks are nouns. short, cold and wise are adjectives." },
      { type: "mcq", q: "Which word is a proper noun in this story?", options: ["Tortoise", "river", "rocks", "wind"], answer: 0, hints: ["A proper noun names a particular character.", "It starts with a capital letter in the story.", "Look for a character's name."], explain: "\"Tortoise\" is used as a character's name, so it is a proper noun with a capital letter." }
